import React from 'react';
import '../styles/theme.css';

export default function Login({ onLoginSuccess }) {
  const handleLogin = (e) => {
    e.preventDefault();
    if (onLoginSuccess) {
      onLoginSuccess();
    }
  };

  return (
    <div className="login-container" style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh', background: '#F4F7F6' }}>
      <div className="form-container" style={{ background: '#FFF', padding: '40px', borderRadius: '8px', boxShadow: '0 4px 12px rgba(0,0,0,0.1)', width: '400px', textAlign: 'center' }}>
        <h2 style={{ color: '#1B4D3E', marginBottom: '5px' }}>RK SONS</h2>
        <p style={{ color: '#666', marginBottom: '25px' }}>Welcome Back, Admin</p>
        
        <form onSubmit={handleLogin}>
          <div className="input-group" style={{ textAlign: 'left', marginBottom: '15px' }}>
            <label style={{ display: 'block', fontSize: '14px', marginBottom: '5px' }}>Mobile Number</label>
            <input type="text" defaultValue="7049183854" style={{ width: '100%', padding: '10px', borderRadius: '4px', border: '1px solid #ccc' }} />
          </div>

          <div className="input-group" style={{ textAlign: 'left', marginBottom: '20px' }}>
            <label style={{ display: 'block', fontSize: '14px', marginBottom: '5px' }}>Password</label>
            <input type="password" defaultValue="••••••••••" style={{ width: '100%', padding: '10px', borderRadius: '4px', border: '1px solid #ccc' }} />
          </div>

          <button type="submit" style={{ width: '100%', background: '#1B4D3E', color: '#FFF', padding: '12px', border: 'none', borderRadius: '4px', fontWeight: 'bold', cursor: 'pointer' }}>
            LOGIN
          </button>
        </form>
      </div>
    </div>
  );
}
